"""
Contract: perceive(observation_history) -> str must never raise.
Output a concise (<2000 char) summary of the current raw observation,
with a delta from the previous observation (if available) to make
actions recoverable from consecutive summaries.
"""

import json
from collections import Counter

def _parse_grid(obs: str):
    """Extract the 2D colour grid as list[list[str]].
    Returns None on failure.
    """
    if not obs:
        return None
    start = obs.find("[[")
    end = obs.rfind("]]")
    if start == -1 or end == -1 or end < start:
        return None
    try:
        grid = json.loads(obs[start : end + 2])
    except Exception:
        return None
    if not grid or not isinstance(grid, list) or not isinstance(grid[0], list):
        return None
    return grid

def _cells_set(grid, bg):
    """Return a set of (row, col, colour) for all non-background cells."""
    s = set()
    for r, row in enumerate(grid):
        for c, col in enumerate(row):
            if col != bg:
                s.add((r, c, col))
    return s

def _format_cells(cells):
    """Format an iterable of (r,c) as space-separated "r,c" pairs,
    sorted by row then column."""
    return " ".join(f"{r},{c}" for r, c in sorted(cells))

def _format_colour_group(colour, cells):
    """Return 'colour: r1,c1 r2,c2 ...'"""
    return f"{colour}: {_format_cells(cells)}"

def perceive(observation_history: list[str]) -> str:
    # Parse current observation
    obs = observation_history[-1] if observation_history else ""
    curr = _parse_grid(obs)
    if curr is None:
        return "parse_error"

    # Determine background (most common colour)
    counts = Counter()
    for row in curr:
        counts.update(row)
    if not counts:
        return "empty_grid"
    bg = counts.most_common(1)[0][0]

    # Collect current non‑background cells per colour
    curr_by_colour = {}
    for r, row in enumerate(curr):
        for c, col in enumerate(row):
            if col != bg:
                curr_by_colour.setdefault(col, []).append((r, c))

    # Build main summary (all non‑background cells)
    main_parts = [f"bg:{bg}"]
    for colour in sorted(curr_by_colour):
        cells = curr_by_colour[colour]
        main_parts.append(_format_colour_group(colour, cells))
    # Add white_rows if white cells exist and background is not white
    white_cells = curr_by_colour.get("white", [])
    if white_cells and bg != "white":
        white_rows = sorted({r for r, c in white_cells})
        main_parts.append(f"white_rows:{','.join(map(str, white_rows))}")
    main_str = "; ".join(main_parts)

    # If there is a previous observation, compute delta
    if len(observation_history) >= 2:
        prev = _parse_grid(observation_history[-2])
        if prev is not None:
            # Determine background for previous (may differ in pathological cases)
            prev_counts = Counter()
            for row in prev:
                prev_counts.update(row)
            prev_bg = prev_counts.most_common(1)[0][0] if prev_counts else bg

            curr_set = _cells_set(curr, bg)
            prev_set = _cells_set(prev, prev_bg)

            added = curr_set - prev_set
            removed = prev_set - curr_set

            if added or removed:
                delta_parts = []
                # Group added by colour
                added_by_colour = {}
                for r, c, col in added:
                    added_by_colour.setdefault(col, []).append((r, c))
                for col in sorted(added_by_colour):
                    delta_parts.append("+" + _format_colour_group(col, added_by_colour[col]))
                # Group removed by colour
                removed_by_colour = {}
                for r, c, col in removed:
                    removed_by_colour.setdefault(col, []).append((r, c))
                for col in sorted(removed_by_colour):
                    delta_parts.append("-" + _format_colour_group(col, removed_by_colour[col]))
                main_str += " ; " + " ; ".join(delta_parts)

    # Ensure non‑empty result
    if not main_str:
        main_str = "empty_summary"
    # Enforce length limit (should be rare to exceed)
    if len(main_str) > 2000:
        main_str = main_str[:2000]
    return main_str
